using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.Expenses.Dtos;using Namaa.Domain.Common.Errors;using Namaa.Domain.Common.Results;namespace Namaa.Application.Expenses.Commands.UpdateExpense;public sealed class UpdateExpenseCommandHandler(IExpenseRepository repository,IApplicationDbContext db):IRequestHandler<UpdateExpenseCommand,Result<ExpenseDto>>{public async Task<Result<ExpenseDto>>Handle(UpdateExpenseCommand request,CancellationToken cancellationToken){var e=await repository.FindForUpdateAsync(request.Id,cancellationToken);if(e is null)return Result.Failure<ExpenseDto>(ExpenseErrors.NotFound);e.Update(request.ExpenseDate,request.Category,request.Description,request.Amount,request.ProjectId);await db.SaveChangesAsync(cancellationToken);return Result.Success(ExpenseDto.FromEntity(e));}}
